local CordageMaker = {}
local PRODUCTS = {
    iron_cordage = { name = "Železna vrvica", ironCost = 1, woodCost = 1, leatherCost = 3, time = 5, cost = 140, prestige = 3, happiness = 2, description = "Železna vrvica za vezanje." },
    bronze_cordage = { name = "Bronasta vrvica", bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 3, time = 7, cost = 340, prestige = 5, happiness = 3, description = "Bronasta vrvica za trdovratne potrebe." },
    silver_cordage = { name = "Srebrna vrvica", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 3, time = 11, cost = 830, prestige = 10, happiness = 4, description = "Srebrna vrvica za plemiške potrebe." },
    gilded_cordage = { name = "Pozlačena vrvica", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 3, time = 15, cost = 1800, prestige = 19, happiness = 5, description = "Pozlačena vrvica za dvorne potrebe." },
    jewel_set_cordage = { name = "Draguljasta vrvica", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 3, time = 19, cost = 3900, prestige = 35, happiness = 7, description = "Draguljasta vrvica za kraljeve potrebe." },
    royal_sovereign_cordage = { name = "Kraljevski suverena vrvica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 4, time = 26, cost = 8400, prestige = 67, happiness = 13, description = "Suverena vrvica z biseri za krono." },
}
local BUILDINGS = {
    cordage_workshop = { name = "Vrvnična delavnica", cost = { gold = 300, wood = 180, stone = 125, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    cordage_house = { name = "Vrvnična hiša", cost = { gold = 1110, wood = 360, stone = 255, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_cordage_atelier = { name = "Mojstrski vrvnični atelje", cost = { gold = 2860, wood = 415, stone = 495, silver = 33, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_cordage_palace = { name = "Suverena vrvnična palača", cost = { gold = 12450, wood = 645, stone = 800, gold = 80, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
CordageMaker.ironStock = 10; CordageMaker.bronzeStock = 8; CordageMaker.woodStock = 12; CordageMaker.leatherStock = 18; CordageMaker.silverStock = 8; CordageMaker.goldStock = 6; CordageMaker.jewelStock = 4; CordageMaker.pearlStock = 4
CordageMaker.productStock = {}; CordageMaker.buildings = {}; CordageMaker.maker = nil; CordageMaker.activeMaking = {}; CordageMaker.totalProducts = 0; CordageMaker.dayTimer = 0
function CordageMaker.init() CordageMaker.ironStock=10; CordageMaker.bronzeStock=8; CordageMaker.woodStock=12; CordageMaker.leatherStock=18; CordageMaker.silverStock=8; CordageMaker.goldStock=6; CordageMaker.jewelStock=4; CordageMaker.pearlStock=4; CordageMaker.productStock={}; CordageMaker.buildings={}; CordageMaker.maker=nil; CordageMaker.activeMaking={}; CordageMaker.totalProducts=0; CordageMaker.dayTimer=0; print("[CordageMaker] Royal Cordage Maker System initialized (6 products, 4 buildings)") end
function CordageMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CordageMaker.maker={name=n or ("Vrvničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrvničar najet: %s (spretnost: %d)",CordageMaker.maker.name,s),"success") end; return true end
function CordageMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CordageMaker.build(id) local ok,e=CordageMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CordageMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CordageMaker.getQualityBonus() local b=0; for _,bd in ipairs(CordageMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CordageMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CordageMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CordageMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CordageMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CordageMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CordageMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CordageMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CordageMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CordageMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CordageMaker.buildings==0 then return false,"Potrebna vrvnična delavnica" end; if not CordageMaker.maker then return false,"Potreben vrvničar" end; return true end
function CordageMaker.make(pt,qty) qty=qty or 1; local ok,e=CordageMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CordageMaker.ironStock=CordageMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CordageMaker.bronzeStock=CordageMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CordageMaker.woodStock=CordageMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CordageMaker.leatherStock=CordageMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CordageMaker.silverStock=CordageMaker.silverStock-d.silverCost*qty end; if d.goldCost then CordageMaker.goldStock=CordageMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CordageMaker.jewelStock=CordageMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CordageMaker.pearlStock=CordageMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CordageMaker.maker then t=math.max(1,t-math.floor(CordageMaker.maker.skill/13)) end; table.insert(CordageMaker.activeMaking,{id="cordage_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CordageMaker.completeMaking(m) local q=1.0+(CordageMaker.getQualityBonus()/100); if CordageMaker.maker then q=q+(CordageMaker.maker.skill/140) end; q=math.min(2.5,q); CordageMaker.productStock[m.productType]=(CordageMaker.productStock[m.productType] or 0)+m.quantity; CordageMaker.totalProducts=CordageMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CordageMaker.maker then CordageMaker.maker.itemsMade=CordageMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CordageMaker.maker.skill=math.min(100,CordageMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrvica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cordage.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CordageMaker.update(dt) if not _G.state then return end; CordageMaker.dayTimer=CordageMaker.dayTimer+dt; if CordageMaker.dayTimer>=30 then CordageMaker.dayTimer=0; for i=#CordageMaker.activeMaking,1,-1 do local m=CordageMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CordageMaker.completeMaking(m); table.remove(CordageMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CordageMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CordageMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CordageMaker.getStats() return {ironStock=CordageMaker.ironStock,bronzeStock=CordageMaker.bronzeStock,woodStock=CordageMaker.woodStock,leatherStock=CordageMaker.leatherStock,silverStock=CordageMaker.silverStock,goldStock=CordageMaker.goldStock,jewelStock=CordageMaker.jewelStock,pearlStock=CordageMaker.pearlStock,productStock=CordageMaker.productStock,numBuildings=#CordageMaker.buildings,hasMaker=CordageMaker.maker~=nil,makerName=CordageMaker.maker and CordageMaker.maker.name or "—",makerSkill=CordageMaker.maker and CordageMaker.maker.skill or 0,activeMaking=#CordageMaker.activeMaking,totalProducts=CordageMaker.totalProducts} end
return CordageMaker
